import numpy as np
from scipy import ndimage
z=np.load('source_pixels.npz')['rgb'].astype(np.float32)
def mode_over(a):
 flat=a.astype(np.uint8).reshape(len(a),-1,3); p=flat[:,:,0].astype(np.uint32)<<16|flat[:,:,1].astype(np.uint32)<<8|flat[:,:,2]
 out=np.empty(p.shape[1],np.uint32)
 for j in range(p.shape[1]):
  u,c=np.unique(p[:,j],return_counts=True);out[j]=u[c.argmax()]
 return np.stack([(out>>16)&255,(out>>8)&255,out&255],1).reshape(a.shape[1:]).astype(np.uint8)
late=mode_over(z[24:]); early=mode_over(z[:8]); plate=late.copy(); plate[35:88,175:211]=early[35:88,175:211]
for t in [0,1,2,3,4,5,6,7,23]:
 d=np.abs(z[t]-plate).max(2)
 m=d>10;lab,n=ndimage.label(m,np.ones((3,3)));cs=[]
 for i in range(1,n+1):
  ys,xs=np.where(lab==i)
  if len(xs)>10:cs.append((len(xs),int(xs.min()),int(ys.min()),int(xs.max()),int(ys.max())))
 print(t,sorted(cs,reverse=True)[:6])
PY"
